CREATE OR REPLACE FUNCTION public.evaluation_acceptance_test() RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE aid uuid:=gen_random_uuid(); uid text:='TEST-'||gen_random_uuid()::text; reviewer text:='TEST-'||gen_random_uuid()::text; qid uuid; txid uuid; v numeric; n integer; blocked boolean; BEGIN BEGIN INSERT INTO public."Users"("ID","Role","Team_ID","Status") VALUES(uid,'Member','acceptance-team','Active'); INSERT INTO public."Evaluation_Permissions"(user_id,screen,team_id,actions,granted_by) VALUES(reviewer,'points_approval','acceptance-team','re','MASTER-ADMIN'); INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by,attendance_points) VALUES(aid,'church','Transactional acceptance test','Member',ARRAY['acceptance-team'],now()-interval '1 hour',now()+interval '1 hour','Published','MASTER-ADMIN',10); PERFORM public.evaluation_submit(aid,'MASTER-ADMIN',jsonb_build_array(jsonb_build_object('user_id',uid,'attendance_status','Present'))); SELECT id,amount INTO txid,v FROM public."Points_Transactions" WHERE user_id=uid; IF v<>10 THEN RAISE EXCEPTION 'Wrong attendance award'; END IF; SELECT coalesce(sum(amount),0) INTO v FROM public."Points_Transactions" WHERE user_id=uid AND status='Approved'; IF v<>0 THEN RAISE EXCEPTION 'Pending points entered official balance'; END IF; PERFORM public.review_points_transaction(txid,reviewer,true,''); SELECT sum(amount) INTO v FROM public."Points_Transactions" WHERE user_id=uid AND status='Approved'; IF v<>10 THEN RAISE EXCEPTION 'Approved points missing'; END IF; blocked:=false; BEGIN PERFORM public.review_points_transaction(txid,reviewer,true,''); EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Duplicate approval allowed'; END IF; blocked:=false; BEGIN PERFORM public.evaluation_submit(aid,'MASTER-ADMIN',jsonb_build_array(jsonb_build_object('user_id',uid,'attendance_status','Present'))); EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Duplicate attendance allowed'; END IF; blocked:=false; BEGIN UPDATE public."Points_Transactions" SET amount=99 WHERE id=txid; EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Reviewed balance editable'; END IF; SELECT count(*) INTO n FROM public."Points_Audit" WHERE transaction_id=txid; IF n<>2 THEN RAISE EXCEPTION 'Audit missing'; END IF; aid:=gen_random_uuid(); INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by,max_attempts) VALUES(aid,'marathon','Transactional marathon test','Member',ARRAY['acceptance-team'],now()-interval '1 hour',now()+interval '1 hour','Published','MASTER-ADMIN',2); INSERT INTO public."Evaluation_Criteria"(activity_id,title,points,options,correct_option) VALUES(aid,'Question',10,'["A","B"]',0) RETURNING id INTO qid; PERFORM public.evaluation_submit(aid,uid,jsonb_build_array(jsonb_build_object('user_id',uid,'answers',jsonb_build_object(qid::text,1)))); PERFORM public.evaluation_submit(aid,uid,jsonb_build_array(jsonb_build_object('user_id',uid,'answers',jsonb_build_object(qid::text,0)))); SELECT count(*) INTO n FROM public."Points_Transactions" WHERE activity_id=aid; IF n<>0 THEN RAISE EXCEPTION 'Marathon awarded before closure'; END IF; blocked:=false; BEGIN PERFORM public.evaluation_submit(aid,uid,jsonb_build_array(jsonb_build_object('user_id',uid,'answers','{}'::jsonb))); EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Attempt limit failed'; END IF; UPDATE public."Evaluation_Activities" SET closed_at=now() WHERE id=aid; PERFORM public.evaluation_finalize(aid); PERFORM public.evaluation_finalize(aid); SELECT count(*),max(amount) INTO n,v FROM public."Points_Transactions" WHERE activity_id=aid; IF n<>1 OR v<>10 THEN RAISE EXCEPTION 'Best attempt or uniqueness failed'; END IF; RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='ACCEPTANCE_TEST_ROLLBACK'; EXCEPTION WHEN NO_DATA_FOUND THEN IF SQLERRM<>'ACCEPTANCE_TEST_ROLLBACK' THEN RAISE; END IF; END; RETURN jsonb_build_object('attendance_award',10,'pending_official',0,'approved_official',10,'audit_events',2,'marathon_best',10,'marathon_awards',1,'duplicate_approval_denied',true,'duplicate_attendance_denied',true,'immutable_history',true,'attempt_limit_enforced',true,'all_test_data_rolled_back',true); END $$;
REVOKE ALL ON FUNCTION public.evaluation_acceptance_test() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluation_acceptance_test() TO service_role;